<script setup lang="ts">import type {Ranking} from '../types/domain';defineProps<{rows:Ranking[]}>();const x=(v:number,n:number)=>120+(v-1)/Math.max(1,n-1)*420;</script><template><svg class="sensitivity-chart" :viewBox="`0 0 600 ${rows.length*28+45}`" aria-label="单权重扰动名次范围"><g v-for="(r,i) in rows" :key="r.alternative_id"><text x="5" :y="i*28+27">{{r.alternative_id}}</text><line x1="120" x2="540" :y1="i*28+23" :y2="i*28+23" class="track"/><line v-if="r.min_rank!=null&&r.max_rank!=null" :x1="x(r.min_rank,rows.length)" :x2="x(r.max_rank,rows.length)" :y1="i*28+23" :y2="i*28+23" class="range"/><circle v-if="r.rank!=null" :cx="x(r.rank,rows.length)" :cy="i*28+23" r="4"/><text x="558" :y="i*28+27">{{r.min_rank}}—{{r.max_rank}}</text></g><text x="120" :y="rows.length*28+35">名次1</text><text x="480" :y="rows.length*28+35">名次{{rows.length}}</text></svg></template>
